// Sample dataset — an array of objects (records).
const rows = [
  { id: 1, name: 'Ada Lovelace',   role: 'Engineer', country: 'UK',  active: true },
  { id: 2, name: 'Alan Turing',    role: 'Scientist', country: 'UK', active: false },
  { id: 3, name: 'Grace Hopper',   role: 'Admiral',  country: 'US',  active: true },
  { id: 4, name: 'Katherine, J.',  role: 'Mathematician', country: 'US', active: true }
];
return rows.map((r) => ({ json: r }));

// Convert all incoming items to a single RFC-4180 CSV string. Pure compute.
const items = $input.all().map((i) => i.json);
if (items.length === 0) return [{ json: { csv: '', rowCount: 0, columns: [] } }];

// Union of all keys, preserving first-seen order.
const cols = [];
for (const obj of items) {
  for (const k of Object.keys(obj)) if (!cols.includes(k)) cols.push(k);
}

const esc = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};

const header = cols.join(',');
const lines = items.map((obj) => cols.map((c) => esc(obj[c])).join(','));
const csv = [header, ...lines].join('\n');

return [{ json: { csv, rowCount: items.length, columns: cols } }];
